const RTL_LANGUAGES = new Set(["ar", "fa", "he", "ps", "ur"]);

export function isRtlLanguage(languageCode: string | null | undefined): boolean {
  return RTL_LANGUAGES.has(languageKey(languageCode));
}

export function storefrontTextDirection(languageCode: string | null | undefined): "ltr" | "rtl" {
  return isRtlLanguage(languageCode) ? "rtl" : "ltr";
}

const SKIP_TRANSLATION_KEYS = new Set([
  "id",
  "type",
  "component",
  "variant",
  "layout",
  "base_layout",
  "slug",
  "image",
  "images",
  "icon",
  "href",
  "url",
  "assetBaseUrl",
  "previewImage",
  "previewImages",
  "logo",
  "logoUrl",
  "backgroundImage",
  "imageCenter",
  "imageLeft",
  "imageRight",
  "primary",
  "secondary",
  "surface",
  "ink",
  "muted",
]);

function languageKey(languageCode: string | null | undefined): string {
  const code = String(languageCode ?? "en").trim().toLowerCase().split("-")[0];
  return code || "en";
}

function dictionaryFor(languageCode: string | null | undefined, localeDictionary: Record<string, string> = {}): Record<string, string> | null {
  const code = languageKey(languageCode);
  if (code === "en") return null;
  const dict = {
    INR: "INR",
    ...(TRANSLATIONS[code] ?? {}),
    ...(COVERAGE_TRANSLATIONS[code] ?? {}),
    ...(DOMAIN_CATALOG_TRANSLATIONS[code] ?? {}),
    ...(THEME_TEXT_TRANSLATIONS[code] ?? {}),
    ...(UI_TRANSLATIONS[code] ?? {}),
    ...(UI_TRANSLATIONS_ADDITIONS[code] ?? {}),
    ...(CART_TRANSLATIONS[code] ?? {}),
    ...(SYSTEM_TRANSLATIONS[code] ?? {}),
    ...(STATIC_PAGE_FALLBACKS[code] ?? {}),
    ...(STATIC_PAGE_TRANSLATIONS[code] ?? {}),
    ...localeDictionary,
  };
  return Object.keys(dict).length ? dict : null;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function translateBySegments(text: string, languageCode: string | null | undefined): string {
  const code = languageKey(languageCode);
  const segments = { ...(SEGMENT_TRANSLATIONS[code] ?? {}), ...(COVERAGE_SEGMENT_TRANSLATIONS[code] ?? {}), ...(DOMAIN_CATALOG_SEGMENT_TRANSLATIONS[code] ?? {}) };
  if (!Object.keys(segments).length) return text;
  const translated = Object.entries(segments)
    .sort(([left], [right]) => right.length - left.length)
    .reduce((current, [source, target]) => current.replace(new RegExp(escapeRegExp(source), "g"), target), text);
  return translated;
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function translateUnknownLatinWords(text: string, languageCode: string | null | undefined): string {
  const code = languageKey(languageCode);
  const words = { ...(WORD_TRANSLATIONS[code] ?? {}), ...(COVERAGE_WORD_TRANSLATIONS[code] ?? {}) };
  if (!Object.keys(words).length) return text;
  return text.replace(/[A-Za-z][A-Za-z'-]*/g, (word) => {
    const translated = words[word.toLowerCase()];
    if (translated !== undefined) return translated;
    return word;
  });
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function transliterateLatinWordToHindi(word: string): string {
  const lower = word.toLowerCase();
  const exact: Record<string, string> = {
    b2b: "बी2बी",
    gst: "जीएसटी",
    moq: "एमओक्यू",
    otp: "ओटीपी",
    ui: "यूआई",
  };
  if (exact[lower]) return exact[lower];
  const pairs: Array<[RegExp, string]> = [
    [/tion/g, "शन"],
    [/sion/g, "शन"],
    [/ing/g, "िंग"],
    [/sh/g, "श"],
    [/ch/g, "च"],
    [/th/g, "थ"],
    [/ph/g, "फ"],
    [/ck/g, "क"],
    [/qu/g, "क्व"],
    [/oo/g, "ू"],
    [/ee/g, "ी"],
    [/ai/g, "ै"],
    [/au/g, "ौ"],
    [/ou/g, "ाउ"],
  ];
  let out = lower;
  for (const [pattern, replacement] of pairs) out = out.replace(pattern, replacement);
  const chars: Record<string, string> = {
    a: "ा",
    b: "ब",
    c: "क",
    d: "द",
    e: "े",
    f: "फ",
    g: "ग",
    h: "ह",
    i: "ि",
    j: "ज",
    k: "क",
    l: "ल",
    m: "म",
    n: "न",
    o: "ो",
    p: "प",
    q: "क",
    r: "र",
    s: "स",
    t: "ट",
    u: "ु",
    v: "व",
    w: "व",
    x: "क्स",
    y: "य",
    z: "ज",
  };
  return out.replace(/[a-z]/g, (char) => chars[char] ?? char);
}

function shouldTranslateString(key: string | null, value: string): boolean {
  const trimmed = value.trim();
  if (!trimmed) return false;
  if (/^(?:https?:)?\/\//i.test(trimmed) || trimmed.startsWith("data:")) return false;
  if (/^#(?:[0-9a-f]{3}){1,2}$/i.test(trimmed)) return false;
  if (/\.(?:png|jpe?g|webp|gif|svg|avif|json|css|js)(?:[?#].*)?$/i.test(trimmed)) return false;
  return !key || !SKIP_TRANSLATION_KEYS.has(key);
}

function translateValue(value: unknown, languageCode: string | null | undefined, key: string | null = null, localeDictionary: Record<string, string> = {}): unknown {
  if (typeof value === "string") return shouldTranslateString(key, value) ? translateText(value, languageCode, localeDictionary) : value;
  if (Array.isArray(value)) return value.map((item) => translateValue(item, languageCode, key, localeDictionary));
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([childKey, child]) => [childKey, translateValue(child, languageCode, childKey, localeDictionary)]));
  }
  return value;
}

export function applyTemplateLanguage(
  template: TemplateFile,
  languageCode: string | null | undefined,
  localeDictionary: Record<string, string> = {},
): TemplateFile {
  if (languageKey(languageCode) === "en") return template;
  return translateValue(template, languageCode, null, localeDictionary) as TemplateFile;
}

export function translateText(text: string, languageCode: string | null | undefined, localeDictionary: Record<string, string> = {}): string {
  const dict = dictionaryFor(languageCode, localeDictionary);
  if (!dict) return text;
  const exact = dict[text.trim()];
  if (exact) return exact;
  // Theme keys are resolved from the merged English base dictionary in
  // loadThemeLocale. For any remaining UI string, preserve the English
  // source text rather than exposing a debug or namespace marker.
  if (/^\[?[A-Za-z][A-Za-z0-9_-]*(?:[.][A-Za-z0-9_-]+)+\]?$/u.test(text.trim())) {
    return "Content unavailable";
  }
  return text;
}

export function isMissingTranslation(text: string, languageCode: string | null | undefined): boolean {
  if (languageKey(languageCode) === "en") return false;
  const dict = dictionaryFor(languageCode);
  return !dict?.[text.trim()];
}

/** Internal preview diagnostics; never used to alter production rendering. */
export function collectMissingTranslationKeys(template: unknown, languageCode: string | null | undefined): string[] {
  const code = languageKey(languageCode);
  if (code === "en") return [];
  const missing = new Set<string>();
  const visit = (value: unknown, key: string | null = null) => {
    if (typeof value === "string") {
      if (shouldTranslateString(key, value) && isMissingTranslation(value, code)) missing.add(value);
      return;
    }
    if (Array.isArray(value)) {
      value.forEach((item) => visit(item, key));
      return;
    }
    if (value && typeof value === "object") Object.entries(value).forEach(([childKey, child]) => visit(child, childKey));
  };
  visit(template);
  return [...missing].slice(0, 200);
}
